BEGIN; DO $test$ DECLARE u uuid:=gen_random_uuid(); r record; result jsonb; BEGIN INSERT INTO auth.users(id) VALUES(u); INSERT INTO public.staff_profiles(user_id,role) VALUES(u,'admin'); PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',u,'aal','aal2','role','authenticated')::text,true); FOR r IN SELECT * FROM (VALUES ('dashboard','today_revenue'),('dashboard','cash_received'),('dashboard','daily_financial_summary'),('dashboard','cash_payment_methods'),('dashboard','sales_performance'),('payment_management','today_revenue'),('payment_management','revenue'),('payment_management','payment_overview'),('payment_management','collected_cash'),('payment_management','table_income'),('dashboard','pending_payment'),('payment_management','pending_payments'),('payment_management','pending_payment'),('dashboard','refunds_adjustments'),('payment_management','refunds'),('dashboard','today_s_orders'),('dashboard','today_orders'),('dashboard','kitchen_orders'),('dashboard','motel_orders'),('dashboard','online_walk_in_orders'),('dashboard','orders_preparing'),('dashboard','ready_for_delivery'),('dashboard','delayed_orders'),('dashboard','table_orders'),('dashboard','motel_orders_tracking'),('dashboard','online_orders_tracking'),('dashboard','walk_in_orders_tracking'),('dashboard','online_orders'),('dashboard','kitchen_queue'),('motel_online_orders','motel_online_orders_overview'),('motel_online_orders','order_tracking'),('motel_online_orders','order_history'),('motel_online_orders','order_details'),('motel_online_orders','room_orders'),('motel_online_orders','ready_for_pickup'),('motel_online_orders','walk_in_order_history'),('customer_management','kitchen_overview'),('customer_management','kitchen_reports'),('customer_management','kitchen_performance_timing'),('customer_management','kitchen_priority_delays'),('dashboard','today_s_customers'),('dashboard','guests_today'),('dashboard','table_occupancy_reports'),('dashboard','table_occupancy'),('tables_orders','table_reports'),('kitchen_management','product_sales_performance'),('kitchen_management','menu_reports'),('dashboard','product_performance'),('kitchen_management','price_change_history'),('kitchen_management','menu_audit_history'),('kitchen_management','revisions'),('dashboard','audit_activity_history'),('dashboard','audit_activity'),('payment_management','audit')) v(section,card) LOOP result:=public.get_cafe_operational_report(r.section,r.card,current_date,current_date); IF jsonb_typeof(result->'rows')<>'array' THEN RAISE EXCEPTION 'Invalid report %',r.card; END IF; END LOOP; BEGIN PERFORM public.get_cafe_operational_report('dashboard','unknown_card',current_date,current_date); RAISE EXCEPTION 'Unknown report permitted'; EXCEPTION WHEN insufficient_privilege THEN NULL; END; END; $test$; ROLLBACK;
